void unit_test_trie_collect_words_prefix_not_found(void) {
    // Setup: Build a trie with some words
    const char *words[] = {"apple", "banana", "cherry"};
    struct trie *trie = helper_build_trie(words, 3);
    TEST_ASSERT_NOT_NULL(trie);

    // Setup: Allocate buffer for results
    int max_words = 10;
    char **buffer = (char **)malloc(max_words * sizeof(char *));
    TEST_ASSERT_NOT_NULL(buffer);
    for (int i = 0; i < max_words; i++) {
        buffer[i] = NULL;
    }

    // Test: Call trie_collect_words with a prefix that does NOT exist in the trie
    // This triggers the path: prefix != NULL and not empty, trie_search returns -1 or NULL
    const char *prefix = "dog"; // Not in trie
    int collected = trie_collect_words(trie, prefix, buffer, max_words);

    // Assertions: Should return 0 because prefix not found
    TEST_ASSERT_EQUAL_INT(0, collected);

    // Cleanup: Free buffer (no strings allocated because collection returned 0)
    free(buffer);
    trie_free(trie);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_trie_collect_words_prefix_not_found);
    return UNITY_END();
